/**
 * Recovery Policy — the DETERMINISTIC enforcement layer.
 *
 * This module is the single source of truth for whether an action is allowed.
 * It is intentionally independent of any LLM output: Bedrock may *recommend* an
 * action, but nothing is dispatched unless `evaluate*()` here returns allowed.
 * Every outbound message and every state-changing tool call must pass through
 * this layer immediately before dispatch — including responses generated by the
 * model. The system prompt is NOT an enforcement mechanism.
 *
 * All decisions are structured and auditable: { allowed, reasonCode, reason,
 * evaluatedAt, constraints }.
 */

import type {
  Account,
  Channel,
  PolicyContext,
  PolicyDecision,
  PolicyReasonCode,
  ResolvedIdentity,
} from './types';

// Sensible defaults (overridable via PolicyContext for tests / per-tenant config).
const DEFAULTS = {
  maxContactsPerWindow: 3,
  minIntervalMs: 20 * 60 * 60 * 1000, // 20h between attempts
  quietStartHour: 21, // 9pm local
  quietEndHour: 8, // 8am local
  minInstallments: 2,
  maxInstallments: 6,
} as const;

/** Account statuses on which NO further collection outreach is allowed. */
const HELD_STATUSES = new Set<Account['status']>(['hardship_hold', 'in_dispute']);
/** Account statuses that are not collectible (nothing owed / already paused). */
const NON_COLLECTIBLE_STATUSES = new Set<Account['status']>(['current']);

function decide(
  allowed: boolean,
  reasonCode: PolicyReasonCode,
  reason: string,
  now: Date,
  constraints?: Record<string, unknown>,
): PolicyDecision {
  return { allowed, reasonCode, reason, evaluatedAt: now.toISOString(), constraints };
}

/**
 * Compute the customer-local hour (0-23) for a given IANA timezone.
 * Falls back to UTC if the timezone is missing/invalid.
 */
export function localHour(now: Date, timezone?: string): number {
  if (!timezone) return now.getUTCHours();
  try {
    const fmt = new Intl.DateTimeFormat('en-US', {
      timeZone: timezone,
      hour: 'numeric',
      hour12: false,
    });
    const parts = fmt.formatToParts(now);
    const h = parts.find((p) => p.type === 'hour')?.value;
    const n = h !== undefined ? parseInt(h, 10) : NaN;
    // Intl may render midnight as "24"; normalize.
    return Number.isFinite(n) ? n % 24 : now.getUTCHours();
  } catch {
    return now.getUTCHours();
  }
}

function isQuietHour(hour: number, start: number, end: number): boolean {
  // Window wraps midnight when start > end (e.g. 21..8).
  return start > end ? hour >= start || hour < end : hour >= start && hour < end;
}

/**
 * Authorize an OUTBOUND MESSAGE on a given channel. This is the gate that EVERY
 * outbound (proactive outreach AND model-generated replies) must pass.
 *
 * Order matters: hard compliance stops (opt-out, holds, restricted) are checked
 * before courtesy limits (quiet hours, frequency).
 */
export function evaluateOutbound(
  account: Account,
  ctx: PolicyContext = {},
): PolicyDecision {
  const now = ctx.now ?? new Date();
  const channel = ctx.channel;

  // 1. Global opt-out — absolute. Nothing goes out, on any channel, ever.
  if (account.optedOut) {
    return decide(false, 'GLOBAL_OPT_OUT', 'Customer has globally opted out of all contact.', now);
  }

  // 2. Restricted (legal / bankruptcy / cease-and-desist) — human only.
  if (account.restricted) {
    return decide(false, 'RESTRICTED_HUMAN_ONLY', 'Account is restricted (legal/bankruptcy); human-only handling.', now);
  }

  // 3. Holds — no further collection on held accounts.
  if (account.status === 'hardship_hold') {
    return decide(false, 'HARDSHIP_HOLD', 'Account is under a hardship hold; collection outreach suppressed.', now);
  }
  if (account.status === 'in_dispute') {
    return decide(false, 'DISPUTE_HOLD', 'Account is in dispute; collection paused pending review.', now);
  }

  // 4. Channel-specific opt-out.
  if (channel && account.optedOutChannels?.includes(channel)) {
    return decide(false, 'CHANNEL_OPT_OUT', `Customer opted out of ${channel}.`, now, { channel });
  }

  // 5. Nothing to collect.
  if (NON_COLLECTIBLE_STATUSES.has(account.status)) {
    return decide(false, 'ACCOUNT_NOT_COLLECTIBLE', `Account status "${account.status}" has no collectible balance.`, now);
  }

  // 6. Quiet hours in the customer's LOCAL time.
  const qs = ctx.quietStartHour ?? DEFAULTS.quietStartHour;
  const qe = ctx.quietEndHour ?? DEFAULTS.quietEndHour;
  const hour = localHour(now, account.timezone);
  if (isQuietHour(hour, qs, qe)) {
    return decide(false, 'QUIET_HOURS', `Within customer-local quiet hours (${qs}:00–${qe}:00); hour is ${hour}.`, now, {
      localHour: hour,
      quietStartHour: qs,
      quietEndHour: qe,
      timezone: account.timezone ?? 'UTC',
    });
  }

  // 7. Minimum interval between attempts.
  const minInterval = ctx.minIntervalMs ?? DEFAULTS.minIntervalMs;
  if (account.lastOutreachAt) {
    const elapsed = now.getTime() - new Date(account.lastOutreachAt).getTime();
    if (elapsed < minInterval) {
      return decide(false, 'MIN_INTERVAL', 'Too soon since the last outreach attempt.', now, {
        elapsedMs: elapsed,
        minIntervalMs: minInterval,
      });
    }
  }

  // 8. Frequency cap per rolling window.
  const cap = ctx.maxContactsPerWindow ?? DEFAULTS.maxContactsPerWindow;
  if ((account.outreachCountWindow ?? 0) >= cap) {
    return decide(false, 'FREQUENCY_CAP', `Reached the max of ${cap} contacts for the current window.`, now, {
      outreachCountWindow: account.outreachCountWindow,
      cap,
    });
  }

  return decide(true, 'ALLOWED', 'Outbound permitted by policy.', now, channel ? { channel } : undefined);
}

/**
 * Authorize access to an account by a resolved identity. An UNVERIFIED or
 * mismatched identity must never reach another customer's account.
 */
export function evaluateAccountAccess(
  account: Account,
  identity: ResolvedIdentity,
  ctx: PolicyContext = {},
): PolicyDecision {
  const now = ctx.now ?? new Date();

  if (identity.verification !== 'verified') {
    return decide(false, 'NOT_AUTHORIZED', 'Identity is not verified; cannot access account details.', now);
  }
  // The account must belong to this canonical customer.
  const owner = account.customerId ?? account.recipientId;
  if (owner !== identity.customerId && account.recipientId !== identity.channelIdentifier) {
    return decide(false, 'NOT_AUTHORIZED', 'Resolved identity does not own this account.', now, {
      accountOwner: owner,
      identityCustomer: identity.customerId,
    });
  }
  return decide(true, 'ALLOWED', 'Account access authorized for verified owner.', now);
}

/**
 * Authorize a PAYMENT PLAN. Enforces installment bounds and that the account is
 * collectible and not held.
 */
export function evaluatePaymentPlan(
  account: Account,
  installments: number,
  ctx: PolicyContext = {},
): PolicyDecision {
  const now = ctx.now ?? new Date();
  const min = ctx.minInstallments ?? DEFAULTS.minInstallments;
  const max = ctx.maxInstallments ?? DEFAULTS.maxInstallments;

  if (HELD_STATUSES.has(account.status)) {
    return decide(false, account.status === 'hardship_hold' ? 'HARDSHIP_HOLD' : 'DISPUTE_HOLD',
      `Cannot create a plan while account is "${account.status}".`, now);
  }
  if (account.pastDueCents <= 0) {
    return decide(false, 'PLAN_INELIGIBLE', 'No past-due balance to split into a plan.', now);
  }
  if (!Number.isInteger(installments) || installments < min || installments > max) {
    return decide(false, 'PLAN_INSTALLMENTS_OUT_OF_RANGE',
      `Installments must be an integer in [${min}, ${max}]; got ${installments}.`, now, { min, max, requested: installments });
  }
  return decide(true, 'ALLOWED', 'Payment plan permitted by policy.', now, { min, max });
}

/**
 * Authorize a monetary amount against the account's past-due balance
 * (0 < amount <= pastDue). Prevents over-collection / nonsensical promises.
 */
export function evaluateAmount(
  account: Account,
  amountCents: number,
  ctx: PolicyContext = {},
): PolicyDecision {
  const now = ctx.now ?? new Date();
  if (!Number.isFinite(amountCents) || amountCents <= 0) {
    return decide(false, 'AMOUNT_OUT_OF_BOUNDS', 'Amount must be a positive number of cents.', now);
  }
  if (amountCents > account.pastDueCents) {
    return decide(false, 'AMOUNT_OUT_OF_BOUNDS', 'Amount exceeds the past-due balance.', now, {
      amountCents,
      pastDueCents: account.pastDueCents,
    });
  }
  return decide(true, 'ALLOWED', 'Amount within bounds.', now);
}
